  gm=("«Абай мектебі» бәйгесі", "Сайттағы викторина, «Шын ба, жалған ба?», «Сәйкестендір» (қара сөз — негізгі ойы), «Әріп шашу»."),
  rf=("«Абай алақаны»", "Алақанның 5 саусағына Абайдың «бес асыл ісі» (талап, еңбек, терең ой, қанағат, рақым) жазылып, оқушы өзі дамытатын біреуін белгілейді. Сайттағы кері байланыс толтырылады."),
